using Microsoft.VisualStudio.TestTools.UnitTesting;
using Payments;

namespace Payments.Tests;

[TestClass]
public class ChargeTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new PaymentGateway();
    }

    [TestMethod]
    public async Task ChargeAsync_ValidToken_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 50.00m);

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrEmpty(result.ChargeId));
    }

    [TestMethod]
    public async Task ChargeAsync_ValidToken_ReturnsUniqueChargeId()
    {
        var result1 = await _gateway.ChargeAsync("tok_valid_visa", 25.00m);
        var result2 = await _gateway.ChargeAsync("tok_valid_visa", 25.00m);

        Assert.AreNotEqual(result1.ChargeId, result2.ChargeId);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task ChargeAsync_EmptyToken_ThrowsArgumentException()
    {
        await _gateway.ChargeAsync("", 10.00m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task ChargeAsync_NullToken_ThrowsArgumentException()
    {
        await _gateway.ChargeAsync(null!, 10.00m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public async Task ChargeAsync_ZeroAmount_ThrowsArgumentOutOfRangeException()
    {
        await _gateway.ChargeAsync("tok_valid_visa", 0m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public async Task ChargeAsync_NegativeAmount_ThrowsArgumentOutOfRangeException()
    {
        await _gateway.ChargeAsync("tok_valid_visa", -5.00m);
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailure()
    {
        var result = await _gateway.ChargeAsync("tok_declined", 50.00m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_LargeAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 9999.99m);

        Assert.IsTrue(result.Success);
    }
}

[TestClass]
public class RefundTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new PaymentGateway();
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccess()
    {
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 50.00m);
        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.IsFalse(string.IsNullOrEmpty(refund.RefundId));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await _gateway.RefundAsync("");
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentException()
    {
        await _gateway.RefundAsync(null!);
    }

    [TestMethod]
    public async Task RefundAsync_InvalidChargeId_ReturnsFailure()
    {
        var result = await _gateway.RefundAsync("ch_nonexistent");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_DuplicateRefund_ReturnsFailure()
    {
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 75.00m);
        await _gateway.RefundAsync(charge.ChargeId);
        var duplicate = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsFalse(duplicate.Success);
    }
}

[TestClass]
public class WebhookTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new PaymentGateway();
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public async Task ProcessWebhookAsync_NullPayload_ThrowsArgumentNullException()
    {
        await _gateway.ProcessWebhookAsync(null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task ProcessWebhookAsync_EmptyPayload_ThrowsArgumentException()
    {
        await _gateway.ProcessWebhookAsync("");
    }

    [TestMethod]
    public async Task ProcessWebhookAsync_ValidChargeSucceeded_ReturnsHandled()
    {
        var payload = """{"type":"charge.succeeded","chargeId":"ch_123"}""";
        var result = await _gateway.ProcessWebhookAsync(payload);

        Assert.IsTrue(result.Handled);
        Assert.AreEqual("charge.succeeded", result.EventType);
    }

    [TestMethod]
    public async Task ProcessWebhookAsync_ValidRefundCreated_ReturnsHandled()
    {
        var payload = """{"type":"refund.created","refundId":"re_456"}""";
        var result = await _gateway.ProcessWebhookAsync(payload);

        Assert.IsTrue(result.Handled);
        Assert.AreEqual("refund.created", result.EventType);
    }

    [TestMethod]
    public async Task ProcessWebhookAsync_UnknownEventType_ReturnsNotHandled()
    {
        var payload = """{"type":"unknown.event","data":{}}""";
        var result = await _gateway.ProcessWebhookAsync(payload);

        Assert.IsFalse(result.Handled);
    }

    [TestMethod]
    public async Task ProcessWebhookAsync_MalformedJson_ReturnsNotHandled()
    {
        var result = await _gateway.ProcessWebhookAsync("{not valid json");

        Assert.IsFalse(result.Handled);
    }
}

